-- Additive metadata only. Existing note/notification/history rows remain untouched.
CREATE TABLE crm_note_realtime_event (
 id_note_realtime_event BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna de intencion duradera de publicacion',
 public_id_note_realtime_event CHAR(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ULID estable para deduplicar reintentos de transporte',
 recipient_user_id_note_realtime_event BIGINT UNSIGNED NOT NULL COMMENT 'Destinatario nativo exclusivo reautorizado al publicar',
 note_id_note_realtime_event BIGINT UNSIGNED NULL COMMENT 'Nota opcional sin contenido ni identificadores comerciales',
 notification_id_note_realtime_event BIGINT UNSIGNED NULL COMMENT 'Aviso ya persistido atomicamente antes de su publicacion',
 kind_note_realtime_event VARCHAR(32) NOT NULL COMMENT 'Tipo versionado de invalidacion segura sin cuerpos privados',
 version_note_realtime_event INT UNSIGNED NULL COMMENT 'Version opcional del contenido nativo',
 collaboration_version_note_realtime_event INT UNSIGNED NULL COMMENT 'Version opcional de colaboracion nativa',
 status_note_realtime_event VARCHAR(16) NOT NULL DEFAULT 'pending' COMMENT 'Pending processing published o failed; publicado nunca significa leido',
 attempts_note_realtime_event TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Intento monotono usado como fencing de lease',
 available_at_note_realtime_event DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Disponibilidad UTC o vencimiento de lease activo',
 occurred_at_note_realtime_event DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Instante UTC de la mutacion original',
 published_at_note_realtime_event DATETIME(3) NULL COMMENT 'Instante UTC del intento de publicacion confirmado por dispatcher',
 last_error_code_note_realtime_event VARCHAR(64) NULL COMMENT 'Codigo tecnico seguro sin texto de errores privados',
 PRIMARY KEY(id_note_realtime_event),
 UNIQUE KEY uq_note_realtime_public_recipient(public_id_note_realtime_event,recipient_user_id_note_realtime_event),
 KEY ix_note_realtime_claim(status_note_realtime_event,available_at_note_realtime_event,id_note_realtime_event),
 KEY ix_note_realtime_recipient(recipient_user_id_note_realtime_event,id_note_realtime_event),
 KEY ix_note_realtime_note(note_id_note_realtime_event,status_note_realtime_event),
 CONSTRAINT fk_note_realtime_recipient FOREIGN KEY(recipient_user_id_note_realtime_event) REFERENCES sec_user(id_user),
 CONSTRAINT fk_note_realtime_note FOREIGN KEY(note_id_note_realtime_event) REFERENCES crm_note(id_note),
 CONSTRAINT fk_note_realtime_notification FOREIGN KEY(notification_id_note_realtime_event) REFERENCES sec_notification(id_notification),
 CONSTRAINT ck_note_realtime_kind CHECK(kind_note_realtime_event IN ('notification.created','notifications.changed','note.changed','note.access_revoked','sync.required')),
 CONSTRAINT ck_note_realtime_status CHECK(status_note_realtime_event IN ('pending','processing','published','failed') AND attempts_note_realtime_event<=5),
 CONSTRAINT ck_note_realtime_version CHECK((version_note_realtime_event IS NULL OR version_note_realtime_event>0) AND (collaboration_version_note_realtime_event IS NULL OR collaboration_version_note_realtime_event>0)),
 CONSTRAINT ck_note_realtime_reference CHECK((kind_note_realtime_event NOT IN ('notification.created','note.changed','note.access_revoked') OR note_id_note_realtime_event IS NOT NULL) AND (kind_note_realtime_event<>'notification.created' OR notification_id_note_realtime_event IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Intenciones realtime aisladas de outbox legacy con entrega al menos una vez';
